public protocol ZkwInboxProtocol : AnyObject {
    
    /**
     * Accept a Request event. Returns the BUNDLE memos to send back.
     */
    func acceptRequest(helloId: Data, myAddress: Data) throws  -> Outgoing
    
    /**
     * After a Bundle event: start the conversation.
     */
    func completeHello(invite: Data, firstText: String) throws  -> Outgoing
    
    /**
     * The per-contact Zcash address we send to for this contact.
     */
    func contactAddress(peer: Data) throws  -> Data
    
    /**
     * Contact ids we have an active session with.
     */
    func contacts() throws  -> [Data]
    
    /**
     * Bytes to show as a QR code / link. `my_address`: a fresh per-contact Unified Address.
     */
    func createInvite(myAddress: Data) throws  -> Data
    
    /**
     * Encrypted snapshot of all chat state. Save after every send/receive.
     */
    func exportSealed(stateKey: Data) throws  -> Data
    
    /**
     * Our public identity (Ed25519 key, 32 bytes). Used as the contact id on the other side.
     */
    func myId() throws  -> Data
    
    /**
     * Feed every received 512-byte memo here. Returns an event, or None for
     * memos that aren't ours, are incomplete chunks, or fail verification.
     */
    func receive(memo: Data, now: UInt64) throws  -> ZkwEvent?
    
    func requests() throws  -> [ZkwRequest]
    
    /**
     * Call on app launch; rotates prekeys weekly. Save state afterwards if it returns true.
     */
    func rotatePrekeysIfDue(now: UInt64) throws  -> Bool
    
    /**
     * 60-digit safety number for verifying a contact in person.
     */
    func safetyNumber(peer: Data) throws  -> String
    
    /**
     * Cold contact: we only know their address.
     */
    func sendHello(theirAddress: Data, myAddress: Data) throws  -> Outgoing
    
    func sendReaction(peer: Data, reaction: String, now: UInt64) throws  -> Outgoing
    
    func sendReceipt(peer: Data, data: Data, now: UInt64) throws  -> Outgoing
    
    func sendText(peer: Data, text: String, now: UInt64) throws  -> Outgoing
    
    /**
     * We scanned someone's invite. Returns the INIT memos to send.
     */
    func startFromInvite(invite: Data, myAddress: Data, firstText: String) throws  -> Outgoing
    
}

