/**
 * Memos to send as ONE shielded transaction (one Orchard output per memo) to `to_address`.
 */
public struct Outgoing {
    public var toAddress: Data
    public var memos: [Data]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(toAddress: Data, memos: [Data]) {
        self.toAddress = toAddress
        self.memos = memos
    }
}



extension Outgoing: Equatable, Hashable {
    public static func ==(lhs: Outgoing, rhs: Outgoing) -> Bool {
        if lhs.toAddress != rhs.toAddress {
            return false
        }
        if lhs.memos != rhs.memos {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(toAddress)
        hasher.combine(memos)
    }
}


