// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.

public enum ZkwEvent {
    
    /**
     * A new contact started a conversation with us (via our invite or accepted request).
     */
    case newSession(peer: Data, text: String
    )
    case message(peer: Data, text: String
    )
    case receipt(peer: Data, data: Data
    )
    case reaction(peer: Data, reaction: String
    )
    case closed(peer: Data
    )
    /**
     * Someone sent a cold HELLO. Show in the Requests inbox; never auto-accept.
     */
    case request(helloId: Data, peer: Data, address: Data
    )
    /**
     * Reply to our HELLO. Pass `invite` to `complete_hello` to start the chat.
     */
    case bundle(peer: Data, invite: Data
    )
}


