        switch variant {
        
        case 1: return .newSession(peer: try FfiConverterData.read(from: &buf), text: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .message(peer: try FfiConverterData.read(from: &buf), text: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .receipt(peer: try FfiConverterData.read(from: &buf), data: try FfiConverterData.read(from: &buf)
        )
        
        case 4: return .reaction(peer: try FfiConverterData.read(from: &buf), reaction: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .closed(peer: try FfiConverterData.read(from: &buf)
        )
        
        case 6: return .request(helloId: try FfiConverterData.read(from: &buf), peer: try FfiConverterData.read(from: &buf), address: try FfiConverterData.read(from: &buf)
        )
        
        case 7: return .bundle(peer: try FfiConverterData.read(from: &buf), invite: try FfiConverterData.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ZkwEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .newSession(peer,text):
            writeInt(&buf, Int32(1))
            FfiConverterData.write(peer, into: &buf)
            FfiConverterString.write(text, into: &buf)
            
        
        case let .message(peer,text):
            writeInt(&buf, Int32(2))
            FfiConverterData.write(peer, into: &buf)
            FfiConverterString.write(text, into: &buf)
            
        
        case let .receipt(peer,data):
            writeInt(&buf, Int32(3))
            FfiConverterData.write(peer, into: &buf)
            FfiConverterData.write(data, into: &buf)
            
        
        case let .reaction(peer,reaction):
            writeInt(&buf, Int32(4))
            FfiConverterData.write(peer, into: &buf)
            FfiConverterString.write(reaction, into: &buf)
            
        
        case let .closed(peer):
            writeInt(&buf, Int32(5))
            FfiConverterData.write(peer, into: &buf)
            
        
        case let .request(helloId,peer,address):
            writeInt(&buf, Int32(6))
            FfiConverterData.write(helloId, into: &buf)
            FfiConverterData.write(peer, into: &buf)
            FfiConverterData.write(address, into: &buf)
            
        
        case let .bundle(peer,invite):
            writeInt(&buf, Int32(7))
            FfiConverterData.write(peer, into: &buf)
            FfiConverterData.write(invite, into: &buf)
            
        }
    }
}


